// Quantized 0..5 digit classifier. The 28x28 binary image must already be
// cropped, aspect-ratio normalized and centered. Training is performed by
// python/train_export.py; this RTL performs inference only.
module digit_mlp_classifier #(
    parameter W1_FILE = "mem/w1.hex",
    parameter B1_FILE = "mem/b1.hex",
    parameter W2_FILE = "mem/w2.hex",
    parameter B2_FILE = "mem/b2.hex"
) (
    input  wire               clk,
    input  wire               rst_n,
    input  wire               load_en,
    input  wire [9:0]         load_addr,
    input  wire               load_pixel,
    input  wire               start,
    output wire               busy,
    output reg                done,
    output reg  [2:0]         digit,
    output reg signed [47:0]  best_score,
    output reg signed [47:0]  margin
);
    localparam integer INPUT_SIZE  = 784;
    localparam integer HIDDEN_SIZE = 32;
    localparam integer CLASS_COUNT = 5;
    // Bounds verified against every fixed weight by checks/logic_rebalance.py.
    localparam integer H_BITS=14, A_BITS=23;
    localparam signed [A_BITS-1:0] MIN_SCORE = {1'b1,{(A_BITS-1){1'b0}}};

    localparam [3:0] ST_IDLE     = 4'd0,
                     ST_L1_READ  = 4'd1,
                     ST_L1_ACC   = 4'd2,
                     ST_L2_READ  = 4'd3,
                     ST_L2_ACC   = 4'd4,
                     ST_DONE     = 4'd5;

    reg [3:0] state;
    (* ram_style="bram" *) reg pixel_mem [0:1023];
    reg pixel_rd;
    (* rom_style="bram" *) reg signed [7:0]  w1_mem [0:INPUT_SIZE*HIDDEN_SIZE-1];
    reg signed [31:0] b1_mem [0:HIDDEN_SIZE-1];
    (* rom_style="bram" *) reg signed [7:0]  w2_mem [0:HIDDEN_SIZE*CLASS_COUNT-1];
    reg signed [31:0] b2_mem [0:CLASS_COUNT-1];
    (* ram_style="bram" *) reg signed [H_BITS-1:0] hidden_mem [0:HIDDEN_SIZE-1];
    reg signed[H_BITS-1:0] hidden_rd;
    (* rom_style="bram" *) reg signed[A_BITS-1:0] bias_mem[0:63];
    reg signed[A_BITS-1:0] bias_rd;integer bias_index;

    reg signed [7:0] w1_rd;
    reg signed [7:0] w2_rd;
    reg [15:0] weight_addr;
    reg [9:0] input_index;
    reg [5:0] hidden_index;
    reg [2:0] class_index;
    wire[5:0] bias_addr=(state==ST_L2_READ || state==ST_L2_ACC)?(6'd32+class_index+6'd1):(hidden_index+6'd1);
    reg signed [A_BITS-1:0] accumulator;
    reg signed [A_BITS-1:0] running_best;
    reg signed [A_BITS-1:0] running_second;
    reg [2:0] running_digit;

    wire signed [A_BITS-1:0] w1_extended = {{(A_BITS-8){w1_rd[7]}}, w1_rd};
    wire signed [H_BITS+7:0] l2_product = $signed(hidden_rd) * $signed(w2_rd);
    // Layers never accumulate simultaneously. Share the 23-bit adder before
    // selecting a result; READ/ACC states and every published result stay exact.
    wire signed[A_BITS-1:0] add_operand=(state==ST_L1_ACC)?
        (pixel_rd?w1_extended:{A_BITS{1'b0}}):
        {{(A_BITS-H_BITS-8){l2_product[H_BITS+7]}},l2_product};
    wire signed[A_BITS-1:0] layer_sum=accumulator+add_operand;
    wire signed[A_BITS-1:0] l1_sum=layer_sum,l2_sum=layer_sum;

    assign busy = (state != ST_IDLE);

    initial begin
        w1_mem[0] = 8'h00;
        w1_mem[1] = 8'h00;
        w1_mem[2] = 8'h00;
        w1_mem[3] = 8'h00;
        w1_mem[4] = 8'h00;
        w1_mem[5] = 8'h00;
