        w2_mem[140] = 8'he3;
        w2_mem[141] = 8'hc9;
        w2_mem[142] = 8'h4d;
        w2_mem[143] = 8'h25;
        w2_mem[144] = 8'hd2;
        w2_mem[145] = 8'h08;
        w2_mem[146] = 8'h3a;
        w2_mem[147] = 8'h3f;
        w2_mem[148] = 8'he3;
        w2_mem[149] = 8'h1f;
        w2_mem[150] = 8'hca;
        w2_mem[151] = 8'h97;
        w2_mem[152] = 8'h00;
        w2_mem[153] = 8'h2a;
        w2_mem[154] = 8'hca;
        w2_mem[155] = 8'hbb;
        w2_mem[156] = 8'h43;
        w2_mem[157] = 8'h56;
        w2_mem[158] = 8'h81;
        w2_mem[159] = 8'h01;
        b2_mem[0] = 32'hfffff664;
        b2_mem[1] = 32'hffffdb1f;
        b2_mem[2] = 32'hfffffdd1;
        b2_mem[3] = 32'h00000452;
        b2_mem[4] = 32'h00000455;
        for(bias_index=0;bias_index<64;bias_index=bias_index+1)bias_mem[bias_index]=0;
        for(bias_index=0;bias_index<32;bias_index=bias_index+1)bias_mem[bias_index]=b1_mem[bias_index];
        for(bias_index=0;bias_index<5;bias_index=bias_index+1)bias_mem[32+bias_index]=b2_mem[bias_index];
    end

    // Registered ROM reads are intended to infer synchronous memories.
    always @(posedge clk) begin
        pixel_rd <= pixel_mem[input_index];
        hidden_rd <= hidden_mem[hidden_index];
        bias_rd <= bias_mem[bias_addr];
        if(rst_n && state==ST_L1_ACC && input_index==INPUT_SIZE-1)
            hidden_mem[hidden_index] <= l1_sum[A_BITS-1] ? {H_BITS{1'b0}} : l1_sum[H_BITS-1:0];
        w1_rd <= w1_mem[weight_addr];
        w2_rd <= w2_mem[weight_addr];
        if (load_en && state == ST_IDLE && load_addr < INPUT_SIZE)
            pixel_mem[load_addr] <= load_pixel;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= ST_IDLE;
            done <= 1'b0;
            digit <= 3'd0;
            best_score <= 48'sd0;
            margin <= 48'sd0;
            input_index <= 10'd0;
            hidden_index <= 6'd0;
            class_index <= 3'd0;
            accumulator <= 48'sd0;
            running_best <= MIN_SCORE;
            running_second <= MIN_SCORE;
            running_digit <= 3'd0;
        end else begin
            done <= 1'b0;
            case (state)
                ST_IDLE: begin
                    if (start) begin
                        weight_addr <= 16'd0;
                        input_index <= 10'd0;
                        hidden_index <= 6'd0;
                        class_index <= 3'd0;
                        accumulator <= {{16{b1_mem[0][31]}}, b1_mem[0]};
                        running_best <= MIN_SCORE;
                        running_second <= MIN_SCORE;
                        running_digit <= 3'd0;
                        state <= ST_L1_READ;
                    end
                end

                ST_L1_READ: state <= ST_L1_ACC;

                ST_L1_ACC: begin
                    if (input_index == INPUT_SIZE-1) begin

                        input_index <= 10'd0;
                        if (hidden_index == HIDDEN_SIZE-1) begin
                            hidden_index <= 6'd0;
                            class_index <= 3'd0;
                            weight_addr <= 16'd0;
                            accumulator <= {{16{b2_mem[0][31]}}, b2_mem[0]};
                            state <= ST_L2_READ;
                        end else begin
                            hidden_index <= hidden_index + 1'b1;
                            weight_addr <= weight_addr + 1'b1;
                            accumulator <= bias_rd;
                            state <= ST_L1_READ;
                        end
                    end else begin
                        input_index <= input_index + 1'b1;
                        weight_addr <= weight_addr + 1'b1;
                        accumulator <= l1_sum;
                        state <= ST_L1_READ;
                    end
                end

                ST_L2_READ: state <= ST_L2_ACC;

                ST_L2_ACC: begin
                    if (hidden_index == HIDDEN_SIZE-1) begin
                        hidden_index <= 6'd0;
                        if (class_index == 0) begin
                            running_best <= l2_sum;
                            running_second <= MIN_SCORE;
                            running_digit <= 3'd0;
                        end else if (l2_sum > running_best) begin
                            running_second <= running_best;
                            running_best <= l2_sum;
                            running_digit <= class_index;
                        end else if (l2_sum > running_second) begin
                            running_second <= l2_sum;
                        end

                        if (class_index == CLASS_COUNT-1) begin
                            state <= ST_DONE;
                        end else begin
                            class_index <= class_index + 1'b1;
                            weight_addr <= weight_addr + 1'b1;
                            accumulator <= bias_rd;
                            state <= ST_L2_READ;
                        end
                    end else begin
                        hidden_index <= hidden_index + 1'b1;
                        weight_addr <= weight_addr + 1'b1;
                        accumulator <= l2_sum;
                        state <= ST_L2_READ;
                    end
                end

                ST_DONE: begin
                    digit <= running_digit;
                    best_score <= running_best;
                    margin <= {{(48-A_BITS){running_best[A_BITS-1]}},running_best} -
                              {{(48-A_BITS){running_second[A_BITS-1]}},running_second};
                    done <= 1'b1;
                    state <= ST_IDLE;
                end

                default: state <= ST_IDLE;
            endcase
        end
    end
endmodule

